export function insertLogoMeta(
  editor: Editor,
  meta: LogoMeta,
  options: InsertTarget = { currentAssets: [] },
): void {
  insertHtml(editor, buildLogoMarkup(meta, getEditorStrings(editor).logoAltSuffix));
  trackAndInjectAsset(editor, getLogoCdnFile(meta), options);
}

